<?php
namespace App\Services; use App\Models\BenchmarkResult;
class BenchmarkScoringService { public function normalized(BenchmarkResult $r):float{$b=$r->benchmark;$min=(float)($b->min_score??0);$max=(float)($b->max_score??100);$range=max($max-$min,.000001);$v=$b->higher_is_better?(((float)$r->score-$min)/$range)*100:(($max-(float)$r->score)/$range)*100;return round(min(100,max(0,$v)),2);} public function composite(object $item):float{$latest=BenchmarkResult::with('benchmark')->where('benchmarkable_type',$item::class)->where('benchmarkable_id',$item->id)->where('verified',true)->where('status','verified')->orderByDesc('tested_at')->orderByDesc('id')->get()->unique('benchmark_id');$x=0;$w=0;foreach($latest as $q){if(!$q->benchmark||!$q->benchmark->is_active)continue;$z=max((float)$q->benchmark->weight,.01);$x+=$this->normalized($q)*$z;$w+=$z;}return $w?round($x/$w,1):0;} public function sync(object $item):void{$latest=BenchmarkResult::with('benchmark')->where('benchmarkable_type',$item::class)->where('benchmarkable_id',$item->id)->where('verified',true)->where('status','verified')->orderByDesc('tested_at')->orderByDesc('id')->get()->unique('benchmark_id');$item->benchmarks=$latest->mapWithKeys(fn($q)=>[$q->benchmark->name=>(float)$q->score])->all();$item->benchmark_score=$this->composite($item);$item->saveQuietly();} public function fingerprint(int $b,string $t,int $i,?string $d,?string $u,float $s):string{return hash('sha256',implode('|',[$b,$t,$i,$d?:'undated',strtolower(trim($u?:'')),number_format($s,4,'.','')]));}}